from pathlib import Path
import re
r=Path(__file__).resolve().parents[1]
p=r/'app.js';s=p.read_text(encoding='utf8')
s=s.replace("./course-data.js?v=ue3","./course-data.js?v=ue4")
s=s.replace('bpmn-labor-ue3-guest-v1','bpmn-labor-ue4-guest-v1').replace('BPMN-Labor-UE3-Lernportfolio.pdf','BPMN-Labor-UE4-Lernportfolio.pdf')
s=s.replace("compareCase:'xor'","compareCase:'xor',roleChoice:'Kundenservice',messageStage:'idle',dataView:'input',endType:'normal'")
s=s.replace('Werden Sie<br>Prozess-Architekt!','Arbeiten Sie<br>bereichsübergreifend!')
s=s.replace('Lernen Sie, Schleifen und parallele Arbeitsabläufe fachlich korrekt zu modellieren. Ihr Ziel: aus einem betrieblichen Beschreibungstext selbstständig ein BPMN-Diagramm in draw.io erstellen.','Sie lernen, wer welche Aufgabe übernimmt, wie Nachrichten zwischen Beteiligten ausgetauscht werden und welche Daten benötigt werden. Am Ende modellieren Sie einen Geschäftsprozess selbstständig aus einem Text.')
s=s.replace('BPMN · UE 3 · LERNKAPITEL','BPMN · UE 4 · LERNKAPITEL')
s=s.replace('Begriffe und Definitionen aus den BPMN-Lernkursen UE 2 und UE 3.','Alle Begriffe aus den Lernkursen UE 2, UE 3 und UE 4.')
s=s.replace("'Schleifen und parallele Arbeitsabläufe'","'Geschäftsprozesse und Zusammenarbeit'")
s=s.replace("'Neue Aufgaben testen Symbolwissen, Reihenfolge, Entscheidungen und die Analyse fehlerhafter Diagramme.'","'Neue Aufgaben prüfen die korrekte BPMN-Modellierung mit beteiligten Bereichen, Nachrichten und Daten.'")
s=s.replace('Testen Sie Ihre wichtigsten Kompetenzen rund um BPMN-Grundsymbole, Abläufe und XOR.','Überprüfen Sie Ihre wichtigsten Kompetenzen rund um Pools, Lanes, Nachrichten und Daten – einschließlich der früheren BPMN-Elemente.')
s=s.replace('Techniken aus UE 2 und UE 3','Techniken aus UE 2, UE 3 und UE 4')
s=s.replace('BPMN-Grundsymbole, Abläufe und XOR.','Pools, Lanes, Nachrichten und Daten.')

new_symbol=r'''function symbolSVG(k,size=58){
 const names={start:'Startereignis',end:'Endereignis',terminate:'Terminierungs-Endereignis',task:'Tätigkeit',xor:'XOR-Gateway',and:'AND-Gateway',pool:'Pool',lane:'Lane',msgSend:'Nachricht senden',msgCatch:'Nachricht empfangen',data:'Datenobjekt',seq:'Sequenzfluss',msgFlow:'Nachrichtenfluss',dataAssoc:'Datenassoziation'};
 const base=`viewBox="0 0 90 70" width="${size*1.3}" height="${size}" role="img" aria-label="${names[k]||'BPMN-Symbol'}"`;
 const stroke='#243252';let shape='';
 if(k==='start')shape=`<circle cx="45" cy="35" r="23" fill="white" stroke="${stroke}" stroke-width="2.5"/>`;
 if(k==='end')shape=`<circle cx="45" cy="35" r="23" fill="white" stroke="${stroke}" stroke-width="6"/>`;
 if(k==='terminate')shape=`<circle cx="45" cy="35" r="23" fill="white" stroke="${stroke}" stroke-width="3"/><circle cx="45" cy="35" r="16" fill="${stroke}"/>`;
 if(k==='task')shape=`<rect x="9" y="12" width="72" height="46" rx="10" fill="white" stroke="${stroke}" stroke-width="2.5"/>`;
 if(k==='and')shape=`<path d="M45 7 L73 35 L45 63 L17 35Z" fill="white" stroke="${stroke}" stroke-width="2.5"/><path d="M45 20 V50 M30 35 H60" stroke="${stroke}" stroke-width="3.5"/>`;
 if(k==='xor')shape=`<path d="M45 7 L73 35 L45 63 L17 35Z" fill="white" stroke="${stroke}" stroke-width="2.5"/><path d="M36 26 L54 44 M54 26 L36 44" stroke="${stroke}" stroke-width="3.5"/>`;
 if(k==='msgCatch'||k==='msgSend')shape=`<circle cx="45" cy="35" r="24" fill="white" stroke="${stroke}" stroke-width="2.5"/><circle cx="45" cy="35" r="20" fill="none" stroke="${stroke}" stroke-width="1.5"/><rect x="30" y="26" width="30" height="19" fill="${k==='msgSend'?stroke:'white'}" stroke="${stroke}" stroke-width="2"/><path d="M30 26 L45 38 L60 26" stroke="${k==='msgSend'?'white':stroke}" stroke-width="2" fill="none"/>`;
 if(k==='data')shape=`<path d="M25 8 H53 L69 24 V63 H25 Z" fill="#FFFDF2" stroke="${stroke}" stroke-width="2.2"/><path d="M53 8 V24 H69" fill="none" stroke="${stroke}" stroke-width="2.2"/>`;
 if(k==='pool'||k==='lane')shape=`<rect x="7" y="10" width="76" height="52" fill="#F4F7FF" stroke="${stroke}" stroke-width="2.2"/><path d="M24 10 V62" stroke="${stroke}" stroke-width="1.8"/>${k==='lane'?'<path d="M24 36 H83" stroke="#9DAFD0" stroke-width="1.7"/>':''}`;
 if(k==='seq')shape=`<path d="M9 35 H77" stroke="${stroke}" stroke-width="3"/><path d="M77 35 L65 28 L65 42 Z" fill="${stroke}"/>`;
 if(k==='msgFlow')shape=`<circle cx="10" cy="35" r="5" fill="white" stroke="${stroke}" stroke-width="2"/><path d="M15 35 H78" stroke="${stroke}" stroke-width="2.5" stroke-dasharray="8 5"/><path d="M78 35 L64 27 M78 35 L64 43" stroke="${stroke}" fill="none" stroke-width="2.5"/>`;
 if(k==='dataAssoc')shape=`<path d="M9 35 H78" stroke="${stroke}" stroke-width="2.2" stroke-dasharray="2 5"/><path d="M78 35 L64 28 M78 35 L64 42" stroke="${stroke}" stroke-width="2.2" fill="none"/>`;
 return `<svg class="symbol-svg" ${base}>${shape}</svg>`;
}
'''
s=re.sub(r'function symbolSVG\(k,size=58\)\{.*?\n\}\nfunction diagramLine',new_symbol+'function diagramLine',s,flags=re.S)

new_interactive=r'''function renderInteractive(which){
 if(which==='intro')return `<div class="visual"><h3>🧩 Wo bleibt die Bestellung? – Ein Fall aus dem Arbeitsalltag</h3><div class="comic-grid"><figure class="comic-frame"><img src="assets/illustrations/campusprint-ue4-einstieg.jpg" alt="Comicillustration eines Textildruck-Unternehmens: Kundenservice, Design und Lager haben unterschiedliche Informationen und sind deshalb unsicher."><figcaption>Die Bestellung ist angekommen, doch Angaben fehlen und die Abteilungen wissen nicht, wer als Nächstes handeln muss.</figcaption></figure><div class="story-panel"><p><strong>Stellen Sie sich vor:</strong> Ihr Jahrgang bestellt 80 Abschluss-Hoodies bei CampusPrint. Die Bestellung ist bezahlt, die Druckdatei ist bereits hochgeladen. Jetzt möchte Ihre Klassensprecherin wissen, wann geliefert wird.</p><p>Im <strong>Kundenservice</strong> liegt die Bestellung, im <strong>Design</strong> wird noch eine überarbeitete Druckdatei geprüft. Das <strong>Lager</strong> hat die endgültige Größenliste nicht erhalten. Jeder Bereich arbeitet, aber niemand kann der Klasse eine eindeutige Auskunft geben.</p><p><strong>Ihre Aufgabe:</strong> Finden Sie heraus, welche Abteilung für welche Arbeit zuständig ist und welche Information wo fehlt. Im Kurs lernen Sie, diese Zusammenarbeit mit BPMN sichtbar zu machen.</p><div class="career-tags"><span>Kundenservice</span><span>Design</span><span>Lager</span><span>Produktion</span></div></div></div><div class="role-sim"><h4>Probieren Sie es aus: Wer soll den nächsten Schritt übernehmen?</h4><div class="switches">${['Kundenservice','Design','Lager','Produktion'].map(x=>`<button data-role="${x}" class="${state.roleChoice===x?'on':''}">${x}</button>`).join('')}</div><div class="market-read">${({Kundenservice:'Kundenservice: Bestellung erfassen, Angaben prüfen und auf Kundenfragen antworten.',Design:'Design: Druckmotiv prüfen und die endgültige Druckdatei bereitstellen.',Lager:'Lager: Größen und Lagerbestand kontrollieren und Ware bereitstellen.',Produktion:'Produktion: Den Druckauftrag nach der Freigabe durchführen.'})[state.roleChoice]}</div></div></div>`;
 if(which==='message')return `<div class="visual"><h3>✉️ So gelangt eine Nachricht vom Kunden zum Unternehmen</h3><p>Ein Kunde und CampusPrint sind zwei eigenständige Prozessbeteiligte. Schicken Sie eine Bestellung oder Rückfrage und beobachten Sie, welche Symbole zum Einsatz kommen.</p><div class="switches"><button data-message-stage="order" class="${state.messageStage==='order'?'on':''}">Bestellung senden</button><button data-message-stage="question" class="${state.messageStage==='question'?'on':''}">Rückfrage senden</button><button data-message-stage="idle">Zurücksetzen</button></div><div class="message-demo"><div class="message-pool"><strong>Pool: Kunde</strong>${symbolSVG(state.messageStage==='question'?'msgCatch':'msgSend',62)}<small>${state.messageStage==='question'?'Rückfrage empfangen':'Bestellung absenden'}</small></div><div class="message-transfer">${symbolSVG('msgFlow',85)}<small>Nachrichtenfluss</small></div><div class="message-pool"><strong>Pool: CampusPrint</strong>${symbolSVG(state.messageStage==='question'?'msgSend':'msgCatch',62)}<small>${state.messageStage==='question'?'Rückfrage absenden':'Bestellung empfangen'}</small></div></div><div class="market-read">${state.messageStage==='idle'?'Wählen Sie eine Nachricht aus.':state.messageStage==='order'?'Die Bestellung wird beim Kunden gesendet und bei CampusPrint empfangen. Zwischen den Pools verläuft ein Nachrichtenfluss.':'Die Rückfrage wird bei CampusPrint gesendet und vom Kunden empfangen. Die Richtung des Nachrichtenflusses kehrt sich um.'}</div><p class="micro">Bei einer Rückfrage geht die Nachricht in umgekehrter Richtung. Ein Nachrichtenfluss ersetzt keinen internen Sequenzfluss.</p></div>`;
 if(which==='data')return `<div class="visual"><h3>📄 Was passiert mit den Informationen?</h3><p>Wählen Sie, ob Sie die Eingabedaten einer Tätigkeit oder das daraus entstehende Ergebnis betrachten möchten.</p><div class="switches"><button data-data-view="input" class="${state.dataView==='input'?'on':''}">Eingabedaten</button><button data-data-view="output" class="${state.dataView==='output'?'on':''}">Ergebnisdaten</button></div><div class="data-demo">${state.dataView==='input'?`${symbolSVG('data',68)}<strong>Bestellung</strong>${symbolSVG('dataAssoc',68)}<div class="data-task">Bestellung prüfen</div>`:`<div class="data-task">Prüfprotokoll erstellen</div>${symbolSVG('dataAssoc',68)}${symbolSVG('data',68)}<strong>Prüfprotokoll</strong>`}</div><div class="market-read">${state.dataView==='input'?'Ein Datenobjekt wird als Eingabe für eine Tätigkeit verwendet. Die Datenassoziation zeigt diesen Bezug.':'Die Tätigkeit erzeugt ein neues Datenobjekt. Auch hier ist die Datenassoziation kein Sequenzfluss.'}</div></div>`;
 if(which==='terminate')return `<div class="visual"><h3>⦿ Was passiert mit den anderen parallelen Arbeiten?</h3><p>Zwei Teams bereiten einen Auftrag parallel vor. Im Lager wird ein schwerwiegendes Hindernis erkannt. Wählen Sie den Endtyp und beobachten Sie die Wirkung.</p><div class="switches"><button data-endtype="normal" class="${state.endType==='normal'?'on':''}">Normales Ende</button><button data-endtype="terminate" class="${state.endType==='terminate'?'on':''}">Terminierung</button></div><div class="terminate-grid"><div class="term-branch"><b>Zweig 1 · Design</b><span>${state.endType==='normal'?'● Druckdatei weiterhin in Arbeit':'■ Druckdatei abgebrochen'}</span></div><div class="term-branch"><b>Zweig 2 · Lager</b>${symbolSVG(state.endType==='normal'?'end':'terminate',72)}<span>${state.endType==='normal'?'Zweig beendet':'Vollständiger Stopp'}</span></div></div><div class="market-read">${state.endType==='normal'?'Ein normales Endereignis beendet nur den Lagerzweig. Die Dateivorbereitung kann weiterhin aktiv sein.':'Das Terminierungs-Endereignis beendet alle noch aktiven Zweige dieses Auftrags, auch die parallele Dateivorbereitung.'}</div></div>`;
 return `<div class="visual"><h3>🛠️ Ihre draw.io-Werkstatt: Aus Text wird ein BPMN-Modell</h3><div class="comic-grid"><figure class="comic-frame"><img src="assets/illustrations/campusprint-ue3-team.jpg" alt="Comicillustration eines Schülers, der aus einem Beschreibungstext ein BPMN-Diagramm entwickelt."><figcaption>Sie arbeiten die Geschäftsprozessbeschreibung selbstständig in draw.io aus.</figcaption></figure><div class="story-panel"><p>Ein guter Einstieg ist, den Text in <strong>Beteiligte, Rollen, Ereignisse, Tätigkeiten, Entscheidungen und Informationen</strong> zu gliedern. Erstellen Sie danach zuerst die Pools und Lanes und ergänzen Sie die passenden BPMN-Elemente.</p><p>Bei den anspruchsvollen Aufgaben erhalten Sie <strong>nur den Beschreibungstext</strong>. Das vollständige Modell entsteht durch Ihre eigene Planung.</p><p><a target="_blank" rel="noopener noreferrer" href="https://app.diagrams.net/">diagrams.net öffnen ↗</a></p><p class="micro">Bei Korrekturaufgaben können Sie eine bearbeitbare .drawio-Datei herunterladen. Eigene Diagramme bleiben auf Ihrem Gerät; der Lernkurs verlangt keinen Upload.</p></div></div></div>`;
}
'''
s=re.sub(r'function renderInteractive\(which\)\{.*?\n\}\nfunction renderLoopDemo',new_interactive+'function renderLoopDemo',s,flags=re.S)

new_slots=r'''if(task.type==='slots'){
 const val=Array.isArray(v)?v:Array(task.slots.length).fill('');
 const symNames={start:'Startereignis',end:'Endereignis',task:'Tätigkeit',xor:'XOR-Gateway',and:'AND-Gateway',pool:'Pool',lane:'Lane',msgSend:'Nachricht senden',msgCatch:'Nachricht empfangen',msgFlow:'Nachrichtenfluss',seq:'Sequenzfluss',data:'Datenobjekt',dataAssoc:'Datenassoziation',terminate:'Terminierungs-Endereignis'};
 const palette=`<div class="drag-help">Ziehen Sie die passenden BPMN-Symbole auf die Lücken. Nicht alle Symbole aus der Auswahl werden benötigt. Auf dem Handy oder per Tastatur können Sie stattdessen die Auswahlliste verwenden.</div><div class="symbol-palette">${[...new Set(task.choices)].map(k=>`<div class="symbol-choice" draggable="true" data-symbol-pick="${task.id}" data-symbol="${k}" title="${symNames[k]}">${symbolSVG(k,57)}<small>${symNames[k]}</small></div>`).join('')}</div>`;
 const slot=(i)=>`<div class="symbol-slot" data-symbol-drop="${task.id}" data-slot="${i}"><div class="slot-symbol">${val[i]?symbolSVG(val[i],57):'<span class="slot-empty">?</span>'}</div><b>${esc(task.slots[i])}</b><select data-slot-answer="${task.id}" data-slot-index="${i}" aria-label="Symbol wählen für ${esc(task.slots[i])}"><option value="">Symbol wählen</option>${[...new Set(task.choices)].map(k=>`<option value="${k}" ${val[i]===k?'selected':''}>${symNames[k]}</option>`).join('')}</select></div>`;
 const seq=(indices)=>`<div class="sequence-row">${indices.map((i,j)=>`${j?'<span class="flow-arrow">→</span>':''}<div class="slot-wrap">${slot(i)}</div>`).join('')}</div>`;
 if(task.layout==='pool')return palette+`<div class="symbol-diagram"><div class="role-slot-head">Beteiligter / Unternehmen</div>${seq([0])}<div class="diagram-split"><div class="split-path"><b>Interner Bereich 1</b>${slot(1)}${slot(2)}</div><div class="split-path"><b>Interner Bereich 2</b>${slot(3)}</div></div></div>`;
 if(task.layout==='message')return palette+`<div class="symbol-diagram"><div class="role-slot-head">Nachrichtenaustausch zwischen zwei Pools</div><div class="message-slots"><div class="message-side"><b>Prozessbeteiligter A</b>${slot(0)}${slot(1)}</div><div class="message-middle"><b>Zwischen den Pools</b>${slot(2)}</div><div class="message-side"><b>Prozessbeteiligter B</b>${slot(4)}${slot(3)}</div></div></div>`;
 if(task.layout==='data')return palette+`<div class="symbol-diagram"><div class="role-slot-head">Information → Arbeitsschritt → Ergebnis</div>${seq([0,1,2,3,4])}</div>`;
 if(task.layout==='terminate')return palette+`<div class="symbol-diagram"><div class="role-slot-head">Parallele Arbeiten: vollständiger Prozessabbruch</div>${seq([0,1,2,3])}</div>`;
 return palette+`<div class="symbol-diagram">${seq(task.slots.map((_,i)=>i))}</div>`;
 }
 if(task.type==='category'||task.type==='match'){'''
s=re.sub(r"if\(task.type==='slots'\)\{.*?\n \}\n if\(task.type==='category'\|\|task.type==='match'\)\{",new_slots,s,flags=re.S)

new_legend=r'''function renderLegend(){
 const groups=[
  {title:'Grundlagen aus UE 2',unit:'UE 2',list:[
   ['Startereignis','Dünner Kreisrand: markiert den Beginn eines Prozesses.','start'],
   ['Tätigkeit (Task)','Abgerundetes Rechteck: kennzeichnet einen auszuführenden Arbeitsschritt.','task'],
   ['Normales Endereignis','Kreis mit dickem Rand: beendet den betreffenden Ablaufzweig.','end'],
   ['Sequenzfluss','Durchgezogener Pfeil mit gefüllter Spitze: zeigt die Reihenfolge innerhalb eines Pools.','seq'],
   ['XOR-Gateway','Raute mit X: genau einer der alternativen Pfade wird ausgewählt; alternative Pfade können zusammengeführt werden.','xor']]},
  {title:'Ergänzungen aus UE 3',unit:'UE 3',list:[
   ['AND-Gateway','Raute mit +: startet alle ausgehenden Zweige; bei der Zusammenführung wird auf alle erforderlichen Zweige gewartet.','and'],
   ['Schleife mit Rückführung','Ein XOR mit einer Bedingung und einem zurückführenden Sequenzfluss wiederholt einen Prozessabschnitt.','loop']]},
  {title:'Neue Elemente aus UE 4',unit:'UE 4',list:[
   ['Pool','Rechteckiger Bereich: stellt einen eigenständigen Beteiligten dar, z. B. Kunde oder Unternehmen.','pool'],
   ['Lane','Unterteilt den Pool in Rollen bzw. Abteilungen und macht Zuständigkeiten sichtbar.','lane'],
   ['Nachrichtenfluss','Gestrichelte Verbindung mit Kreis am Ausgang und offenem Pfeil: zwischen zwei verschiedenen Pools.','msgFlow'],
   ['Nachricht senden','Zwischenereignis: doppelter Kreis mit gefülltem Briefumschlag.','msgSend'],
   ['Nachricht empfangen','Zwischenereignis: doppelter Kreis mit ungefülltem Briefumschlag; wartet auf die Nachricht.','msgCatch'],
   ['Datenobjekt','Dokumentsymbol mit umgeknickter Ecke: verwendete bzw. erzeugte Informationen.','data'],
   ['Datenassoziation','Gepunktete Verbindung zwischen Datenobjekt und Tätigkeit; sie steuert den Ablauf nicht.','dataAssoc'],
   ['Terminierungs-Endereignis','Endereignis mit ausgefülltem Innenkreis; beendet alle aktiven Zweige der betreffenden Prozessinstanz.','terminate']]}
 ];
 const icon=k=>k==='loop'?`<span class="future-icon">↩</span>`:symbolSVG(k,63);
 return heading('BPMN-Syntaxlegende','Alle verbindlichen Elemente aus UE 2, UE 3 und UE 4 mit Form und Bedeutung. Diese vollständige Übersicht bleibt auch für die weiteren Anwendungen erhalten.')+groups.map(group=>`<div class="section-head"><h2>${group.title}</h2></div><div class="legend-grid">${group.list.map(([t,d,k])=>`<article class="legend-card"><div class="legend-icon">${icon(k)}</div><h3>${t}</h3><p>${d}</p><span class="pill ${group.unit==='UE 4'?'alt':'weak'}">${group.unit}</span></article>`).join('')}</div>`).join('')+`<div class="info-note"><b>Wichtig:</b> In UE 4 lernen Sie die letzten neuen BPMN-Elemente kennen. In UE 5 wenden Sie die gesamte Syntax auf andere Geschäftsprozesse an. Verwenden Sie bei allen Diagrammen die passenden Symbole und Verbindungen.</div>`;
}
'''
s=re.sub(r'function renderLegend\(\)\{.*?\nfunction renderTeacher',new_legend+'function renderTeacher',s,flags=re.S)
s=s.replace("if(button.dataset.branch){state.branch=button.dataset.branch;render();return}","if(button.dataset.branch){state.branch=button.dataset.branch;render();return}\n  if(button.dataset.role){state.roleChoice=button.dataset.role;render();return}\n  if(button.dataset.messageStage){state.messageStage=button.dataset.messageStage;render();return}\n  if(button.dataset.dataView){state.dataView=button.dataset.dataView;render();return}\n  if(button.dataset.endtype){state.endType=button.dataset.endtype;render();return}")
# old code has a different event handler? we'll check later
s=s.replace('Kapitel mit Schleifen und parallelen Abläufen','Kapitel mit Zusammenarbeit, Nachrichten und Daten')
p.write_text(s,encoding='utf8')
# API isolate UE4 storage + support new symbols
p=r/'netlify/functions/api.mjs';api=p.read_text(encoding='utf8').replace('bpmn_ue3_session','bpmn_ue4_session').replace('bpmn-ue3-','bpmn-ue4-')
api=api.replace("['start','end','task','xor','and']","['start','end','task','xor','and','pool','lane','msgSend','msgCatch','msgFlow','seq','data','dataAssoc','terminate']")
api=api.replace("'BPMN-Labor-UE3'","'BPMN-Labor-UE4'")
p.write_text(api,encoding='utf8')
# index changes
p=r/'index.html';html=p.read_text(encoding='utf8').replace('UE 3','UE 4').replace('ue3','ue4').replace('Schleifen und parallele Abläufe','Geschäftsprozesse über Abteilungsgrenzen hinweg')
p.write_text(html,encoding='utf8')
# add CSS
p=r/'styles.css';css=p.read_text(encoding='utf8')
css+='''\n/* UE 4 – Ablauf- und Informationsdiagramme */\n.role-sim{margin:20px 0;padding:18px;border:1px solid #dce4f4;border-radius:14px;background:#f7faff}\n.role-sim h4{margin:0 0 12px}\n.message-demo{display:flex;align-items:center;justify-content:space-around;gap:14px;flex-wrap:wrap;margin:18px 0;padding:18px;background:#fafbff;border:1px solid #e0e6f1;border-radius:13px}\n.message-pool{display:flex;min-width:190px;align-items:center;flex-direction:column;gap:9px;flex:1;border:2px solid #96a9ce;padding:12px;border-radius:9px;background:#fff}\n.message-pool strong{font-size:13px}.message-pool small{font-size:12px;color:#526280}\n.message-transfer{display:flex;align-items:center;flex-direction:column;color:#6151a1;font-size:12px}\n.data-demo{display:flex;gap:10px;align-items:center;justify-content:center;flex-wrap:wrap;padding:20px;background:#f7faff;border:1px solid #e0e6f1;border-radius:12px;margin-bottom:14px}\n.data-task{padding:16px 22px;background:#fff;border:2px solid #6c8fbe;border-radius:15px;font-weight:700;font-size:13px}\n.terminate-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:18px 0}\n.term-branch{display:flex;align-items:center;flex-direction:column;justify-content:center;gap:10px;min-height:155px;border:2px dashed #bac9df;background:#fafbff;border-radius:13px;font-size:13px;text-align:center;padding:13px}\n.term-branch span{color:#596780}.term-branch svg{flex-shrink:0}\n.role-slot-head{text-align:center;font-size:13px;font-weight:800;color:#42527e;margin-bottom:12px}\n.message-slots{display:grid;grid-template-columns:1fr minmax(160px,.6fr) 1fr;gap:12px;align-items:start}\n.message-side{padding:12px;border:2px solid #aab8d5;border-radius:13px;display:flex;flex-direction:column;align-items:center;gap:10px;background:#fdfdff}\n.message-middle{padding:12px;border:1px dashed #aab8d5;border-radius:13px;display:flex;flex-direction:column;align-items:center;gap:10px;background:#fff}\n.message-side>b,.message-middle>b{font-size:12px;color:#596781}\n@media(max-width:760px){.message-slots{grid-template-columns:1fr}.message-demo{flex-direction:column}.message-transfer{transform:rotate(90deg)}.terminate-grid{grid-template-columns:1fr}}\n'''
p.write_text(css,encoding='utf8')
print('UE4 app/backend/index/styles patched')
